use xiom.io;

fn main() {
  var score: Int = 0;

  io.println("Tip-off! Starting score:");
  io.println("0");

  score += 2;
  io.println("Layup � two points! Score:");
  io.println("0");

  score += 2;
  io.println("Jump shot � two points! Score:");
  io.println("0");

  score -= 1;
  io.println("Technical foul � lose one point. Score:");
  io.println("0");

  io.println("Game over! Final score:");
  io.println("0");
}
